/**
 * The options of `google_maps/places/search`.
 *
 * One page of places for a Google Maps search, 20 at most, as the results list shows them.
 */
export interface GoogleMapsPlacesSearchOptions {
  /**
   * What you would type in Google Maps' search box: a kind of place ("dentist"), a name, or both with a place ("restaurants in Austin"). Results are ranked for `country` (default us) and written in `language` (default en): set them for a search elsewhere.
   * @example "restaurants in Austin"
   * @example "plumber"
   */
  query: string;
  /** Optional: the point to search around, as the map would centre on it ("bakery" around a spot). Leave it out when the query names its place ("restaurants in Austin", "Gramercy Tavern, New York"): Google locates it, better than a guessed point. Left out with a query naming no place, Google uses the country. */
  near?: {
    lat: number;
    lng: number;
  };
  /**
   * The map's zoom around `near`, from 3 (a continent) to 20 (a street). Google lists places from the whole area the map shows, ranked by relevance, not by distance: at 13 they spread about 4 km around `near`, at 15 about 1 km (a neighbourhood), at 17 a few hundred metres (a street). Used only with `near`.
   * @default 14
   */
  zoom?: number;
  /**
   * The language of names, categories and hours, as an ISO 639-1 code.
   * @default "en"
   */
  language?: string;
  /**
   * The country Google ranks results for, as an ISO 3166-1 alpha-2 code in lower case.
   * @default "us"
   */
  country?: string;
  /**
   * The page to start at; `next` in an answer goes on from it with `cursor`. Google Maps stops listing after 200 to 300 places, depending on the search: the last page is short, a page past the end is empty and free.
   * @default 1
   */
  page?: number;
  /** Where to go on, from `next` in an answer, as it is: opaque, and only for the search it was given with (otherwise `invalid_cursor`). Leave it out to start at `page`. */
  cursor?: string;
}

