/** A record of `google_maps/reviews/list`. */
export interface GoogleMapsReviewsListRecord {
  /** The kind of record: a review, whichever site it comes from. */
  object: 'review';
  /** Google's id of the review, stable across languages and sorts. */
  id: string;
  /** Its rank in this order, across pages: 21 is the first of page 2. */
  position: number;
  /** The place reviewed, so reviews of several places can be told apart. */
  place: {
    /** The place's cid, as google_maps/places/search gives it in `ids.cid`. */
    cid: string;
    /** The place on Google Maps. */
    url: string;
  };
  rating: {
    value: number;
    /** The best possible value. */
    scale: 5;
  };
  /** The author's own words, whole, in their language (`language`), line breaks as \n; null for a rating alone. Quote this as what the author wrote. */
  text: string | null;
  /** The text's language, ISO 639-1, as Google detects it. */
  language: string | null;
  /** Google's translation of `text` into the call's `language`, when the review is written in another. */
  translation: {
    language: string;
    /** Google's machine translation, not the author's words: say so when you quote it. */
    text: string;
  } | null;
  /** When the review was posted, or last edited when `is_edited` (the first date is then not given), UTC. Tell reviews apart by `id`, never by date. */
  published_at: string;
  is_edited: boolean;
  /** When the author says they went, when they said. */
  visit: {
    /** YYYY-MM; null in a language we do not read yet. */
    month: string | null;
    /** As Google writes it, in the call's language. */
    text: string;
  } | null;
  /** People who reacted to the review (likes and other reactions). */
  reaction_count: number | null;
  author: {
    name: string;
    /** The author's Google Maps contributor id. */
    id: string | null;
    /** The author's reviews on Google Maps. */
    url: string | null;
    photo_url: string | null;
    /** Reviews the author has written, all places. */
    review_count: number | null;
    /** Photos the author has posted, all places. */
    photo_count: number | null;
    is_local_guide: boolean;
  };
  /** The photos posted with the review. */
  photo_urls: string[];
  /** The place's reply, when it gave one (Google shows no date for it). */
  owner_reply: {
    text: string;
  } | null;
  /** What the reviewer added beyond the text: a rating of an aspect (`rating`, 1 to 5), or answers to Google's questions (`answers`). `id` is stable across languages; `label` and the answers are in `language`. */
  aspects: Array<{
    id: string;
    label: string | null;
    rating: number | null;
    answers: string[] | null;
  }>;
  /** The review on Google Maps. */
  url: string | null;
  /** The place whose reviews these values were read from. */
  source_url: string;
  /** When they were read, UTC. */
  observed_at: string;
}

