/**
 * The options of `tripadvisor/reviews/list`.
 *
 * One page of a TripAdvisor place's reviews (a hotel, a restaurant, an attraction, a tour), 20 at most, each with its rating out of 5, title, text, the visit, the kind of traveler, sub-ratings, tips, photos, the reviewer and the owner's response.
 */
export interface TripadvisorReviewsListOptions {
  /**
   * The place: its page on TripAdvisor, from any of its sites (a hotel's, a restaurant's, an attraction's, a tour's, or one of its reviews' pages: the address holds -d<number>-), or that number alone (119768). A city's page has none and is refused.
   * @example "https://www.tripadvisor.com/Hotel_Review-g60750-d119768-Reviews-Doubletree_By_Hilton_Hotel_San_Diego_Del_Mar-San_Diego_California.html"
   */
  place: string;
  /**
   * The order the list offers: newest written first; detailed (TripAdvisor's mix of recency and how much a review says); most_insightful, offered on tours and tickets (elsewhere TripAdvisor answers in the newest order).
   * @default "newest"
   */
  sort?: 'newest' | 'detailed' | 'most_insightful';
  /**
   * The reviews of these ratings only (any of them), as the list's Traveler rating filter. All when not set.
   * @example [1,2]
   */
  ratings?: number[];
  /** The reviews of these kinds of traveler only (any of them), as the Traveler type filter. All when not set. */
  traveler_types?: Array<'families' | 'couples' | 'solo_travelers' | 'business_travelers' | 'groups_of_friends'>;
  /**
   * The reviews written in these months only (1 is January), of any year, as the Time of year filter: the month the review was written, not the visit's (checked on 26/11). All when not set.
   * @example [6,7,8]
   */
  months?: number[];
  /**
   * The reviews in one language only, as the list's Read reviews in: those written in it and TripAdvisor's machine translations into it (`translation` says which). Its code: en, fr, es, he, zh-CN... All when not set; then a review comes in English when TripAdvisor has a translation of it, else as written.
   * @example "es"
   */
  language?: string;
  /**
   * A word or a few to search the reviews for, as the list's search box (pool).
   * @example "pool"
   */
  query?: string;
  /**
   * Only the reviews TripAdvisor marks with a traveler safety alert.
   * @default false
   */
  safety_alerts_only?: boolean;
  /**
   * TripAdvisor's locale for the visit (en-US, fr-FR...); the reviews' language is `language`'s.
   * @default "en-US"
   * @example "en-US"
   */
  locale?: string;
  /** Where to go on, from `next` in an answer, as it is: opaque, and only for the place, sort and filters it was given with (otherwise `invalid_cursor`). */
  cursor?: string;
}

